"use client"

// Bollard UI — hidden-content-check · MIT licence · https://bollard-ui.vercel.app/components/hidden-content-check

import * as React from "react"
import { Check, ChevronDown, EyeOff, FileWarning, Loader2, ShieldCheck, Trash2 } from "lucide-react"
import { AnimatePresence, animate, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

import { inspectHiddenContent, type HiddenFinding, type HiddenKind, type HiddenReport } from "./inspect"

export { inspectHiddenContent, isInternalLink, readZip, type HiddenFinding, type HiddenKind, type HiddenReport, type HiddenSeverity } from "./inspect"

export const HIDDEN_CONTENT_CHECK_MESSAGES = {
  checking: "Looking inside {file}…",
  clean: "Nothing hidden in {file}. What you see is what they get.",
  found: "{file} carries one thing you can't see on screen.|{file} carries {count} things you can't see on screen.",
  foundAudience: "{file} carries one thing you can't see on screen, and {audience} will get it.|{file} carries {count} things you can't see on screen, and {audience} will get all of them.",
  locked: "Can't look inside {file}: it's an old .xls/.doc format or password-protected. Save it as .xlsx/.docx, or share a PDF.",
  unreadable: "Couldn't read {file}. Check it before sharing.",
  tooLarge: "{file} is too large to check here.",
  kind: {
    "hidden-sheet": "Hidden sheet “{where}” with {count} row|Hidden sheet “{where}” with {count} rows",
    "hidden-rows": "{count} hidden row in “{where}”|{count} hidden rows in “{where}”",
    "hidden-columns": "{count} hidden column in “{where}”|{count} hidden columns in “{where}”",
    "tracked-changes": "{count} tracked change, deleted text still readable|{count} tracked changes, deleted text still readable",
    "hidden-text": "{count} passage of hidden text|{count} passages of hidden text",
    comments: "{count} comment|{count} comments",
    "speaker-notes": "Speaker notes on {count} slide|Speaker notes on {count} slides",
    "hidden-slides": "{count} hidden slide|{count} hidden slides",
    "embedded-files": "{count} embedded file|{count} embedded files",
    "external-links": "A link to a file on an internal drive|Links to {count} files on internal drives",
    author: "Author and company details",
  } satisfies Record<HiddenKind, string>,
  veryHidden: "Very hidden: Excel's Unhide menu doesn't list it.",
  show: "Show what's in it",
  hide: "Hide preview",
  keep: "Meant to be there",
  kept: "Kept",
  remove: "Remove",
  removing: "Removing…",
  stillThere: "Still in the file after removing. Check it by hand.",
  removeFailed: "Couldn't remove it. Try again or fix it in the app.",
  advice: "Safest for a public reply: share a PDF or CSV with only the answer, not the working file.",
  share: "Share {file}",
  shareAnyway: "Share with {count} hidden item|Share with {count} hidden items",
  blocked: "Check the hidden item above first, or press again to share anyway.|Check the {count} hidden items above first, or press again to share anyway.",
  shareUnchecked: "Share without checking",
  blockedUnchecked: "Nothing inside could be checked. Press again to share it anyway.",
  sharing: "Sharing…",
}

// Plural strings are written "one|other".
type Messages = Omit<typeof HIDDEN_CONTENT_CHECK_MESSAGES, "kind"> & { kind: Record<HiddenKind, string> }

export interface HiddenContentCheckProps extends Omit<React.ComponentProps<"section">, "children"> {
  /** The .xlsx, .docx or .pptx about to be shared. `null` clears the check. */
  file: File | Blob | null | undefined
  /** Name to show when `file` is a Blob without one. */
  fileName?: string
  /** Who will receive it, e.g. "the public". Named in the summary when set. */
  audience?: string
  /** Shares the file. May return a Promise; the button shows a pending state and can't fire twice. */
  onShare?: (report: HiddenReport) => void | Promise<void>
  /** Removes one finding and returns the cleaned file. The result is re-checked before it counts. */
  onRemove?: (finding: HiddenFinding, file: File | Blob) => Promise<File | Blob>
  /** Fires with each report, including after a removal. */
  onReportChange?: (report: HiddenReport) => void
  /** Override any visible string, including per-kind finding text. */
  messages?: Partial<Omit<Messages, "kind">> & { kind?: Partial<Record<HiddenKind, string>> }
}

/** Fills {placeholders}. A "one|other" template picks its form from `count`. */
const fill = (t: string, v: Record<string, string | number>) => (t.includes("|") ? t.split("|")[Number(String(v.count).replace(/\D/g, "")) === 1 ? 0 : 1] : t).replace(/\{(\w+)\}/g, (k, key: string) => String(v[key] ?? k))
const fmt = (n: number) => n.toLocaleString("en-US")
const chip =
  "inline-flex h-7 items-center gap-1 rounded-md border bg-background px-2.5 text-xs font-medium outline-none transition-colors hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-60 dark:bg-input/30"
const tone = {
  high: "border-red-500/40 bg-red-500/5 dark:bg-red-500/10",
  medium: "border-amber-500/40 bg-amber-500/5 dark:bg-amber-500/10",
  low: "border-border bg-muted/40",
}

/**
 * Stops a shared spreadsheet, document or deck leaking what's hidden in it (the PSNI FOI reply whose
 * hidden tab named all 9,483 officers and staff; the UN report whose tracked changes kept the names it
 * deleted). Before sharing, it opens the file in the browser and lists what isn't on screen: hidden and
 * very hidden sheets, hidden rows and columns, tracked deletions, hidden text, comments, speaker notes,
 * hidden slides, embedded workbooks, links to internal drives and author details. Each one can be
 * previewed (the hidden tab's real first rows), kept on purpose or removed through `onRemove`, whose
 * result is re-checked. Sharing with high-risk items open takes a second, deliberate press.
 */
export function HiddenContentCheck({ file, fileName, audience, onShare, onRemove, onReportChange, messages, className, ...props }: HiddenContentCheckProps) {
  const m: Messages = { ...HIDDEN_CONTENT_CHECK_MESSAGES, ...messages, kind: { ...HIDDEN_CONTENT_CHECK_MESSAGES.kind, ...messages?.kind } }
  const [current, setCurrent] = React.useState<File | Blob | null>(file ?? null)
  const [report, setReport] = React.useState<HiddenReport | null>(null)
  const [open, setOpen] = React.useState<string | null>(null)
  const [kept, setKept] = React.useState<Set<string>>(new Set())
  const [busy, setBusy] = React.useState<string | null>(null)
  const [notes, setNotes] = React.useState<Record<string, string>>({})
  const [armed, setArmed] = React.useState(false)
  const [sharing, setSharing] = React.useState(false)
  const [status, setStatus] = React.useState("")
  const run = React.useRef(0)
  const checked = React.useRef<File | Blob | null>(null)
  const rootRef = React.useRef<HTMLElement>(null)
  const shareRef = React.useRef<HTMLButtonElement>(null)
  const reportRef = React.useRef(onReportChange)
  reportRef.current = onReportChange
  const reduce = useReducedMotion()
  const id = React.useId()
  const name = fileName ?? (file instanceof File ? file.name : "This file")

  React.useEffect(() => setCurrent(file ?? null), [file])
  React.useEffect(() => {
    if (current && current === checked.current) return // a cleaned file we have already re-checked
    const token = ++run.current
    setReport(null)
    setArmed(false)
    if (!current) return
    inspectHiddenContent(current).then((r) => {
      if (token !== run.current) return // a newer file arrived while this one was being read
      setReport(r)
      // Open on the worst finding, so the hidden tab's real rows are the first thing seen.
      setOpen(r.findings.find((f) => f.preview.length)?.id ?? null)
      reportRef.current?.(r)
    })
  }, [current])
  React.useEffect(() => {
    setKept(new Set())
    setNotes({})
    setOpen(null)
  }, [file])

  const findings = report?.findings ?? []
  const open_ = findings.filter((f) => f.severity !== "low" && !kept.has(f.id))
  // A file we couldn't look inside (old format, password, too big) may hide anything, so it also takes a second press.
  const unchecked = !!report?.error
  // The warning only stands while something is still open; clearing the last item disarms it.
  const warn = armed && (open_.length > 0 || unchecked)
  const summary = !current
    ? ""
    : !report
      ? fill(m.checking, { file: name })
      : report.error
        ? fill({ locked: m.locked, unreadable: m.unreadable, "too-large": m.tooLarge }[report.error], { file: name })
        : findings.length
          ? fill(audience ? m.foundAudience : m.found, { file: name, count: findings.length, audience: audience ?? "" })
          : fill(m.clean, { file: name })

  // One status line, said once per report rather than on every render.
  React.useEffect(() => {
    const t = setTimeout(() => setStatus(report ? summary : ""), 400)
    return () => clearTimeout(t)
  }, [report, summary])

  const focusNext = (after: string) => {
    requestAnimationFrame(() => {
      const ids = open_.map((f) => f.id).filter((x) => x !== after)
      const next = ids.length ? rootRef.current?.querySelector<HTMLElement>(`[data-finding="${CSS.escape(ids[0])}"] button`) : null
      ;(next ?? shareRef.current)?.focus()
    })
  }

  const keep = (f: HiddenFinding) => {
    setKept((s) => new Set(s).add(f.id))
    focusNext(f.id)
  }

  const remove = async (f: HiddenFinding) => {
    if (!onRemove || !current || busy) return
    setBusy(f.id)
    const token = run.current
    try {
      const cleaned = await onRemove(f, current)
      const again = await inspectHiddenContent(cleaned)
      if (token !== run.current) return // the file was swapped while removing
      checked.current = cleaned
      setCurrent(cleaned)
      setReport(again)
      reportRef.current?.(again)
      const still = again.findings.some((x) => x.id === f.id)
      setNotes((n) => ({ ...n, [f.id]: still ? m.stillThere : "" }))
      if (!still) focusNext(f.id)
    } catch {
      setNotes((n) => ({ ...n, [f.id]: m.removeFailed }))
    } finally {
      setBusy(null)
    }
  }

  const share = async () => {
    if (!report || sharing) return
    if ((open_.length || unchecked) && !armed) {
      setArmed(true)
      if (!reduce && rootRef.current) animate(rootRef.current, { x: [0, -6, 6, -3, 0] }, { duration: 0.3 })
      if (open_.length) rootRef.current?.querySelector<HTMLElement>(`[data-finding="${CSS.escape(open_[0].id)}"] button`)?.focus()
      return
    }
    setSharing(true)
    try {
      await onShare?.(report)
    } catch {
      // The caller reports its own failure; the button just becomes usable again.
    } finally {
      setSharing(false)
      setArmed(false)
    }
  }

  return (
    <section
      ref={rootRef}
      data-slot="hidden-content-check"
      data-state={!report ? "checking" : report.error ? "error" : open_.length ? "found" : "clear"}
      aria-labelledby={`${id}-summary`}
      className={cn("grid w-full min-w-0 gap-3 text-sm", className)}
      {...props}
    >
      {current && (
        <p id={`${id}-summary`} className={cn("flex gap-2", report?.error || findings.length ? "text-foreground" : "text-muted-foreground")}>
          {!report ? (
            <Loader2 aria-hidden className="mt-0.5 size-4 shrink-0 animate-spin" />
          ) : report.error || findings.length ? (
            <FileWarning aria-hidden className="mt-0.5 size-4 shrink-0 text-amber-600 dark:text-amber-400" />
          ) : (
            <ShieldCheck aria-hidden className="mt-0.5 size-4 shrink-0 text-emerald-600 dark:text-emerald-400" />
          )}
          <span className="min-w-0 break-words">{summary}</span>
        </p>
      )}

      {findings.length > 0 && (
        <ul className="grid gap-2">
          <AnimatePresence initial={false}>
            {findings.map((f, i) => {
              const isKept = kept.has(f.id)
              const showing = open === f.id
              const table = f.kind.startsWith("hidden-sheet") || f.kind === "hidden-rows" || f.kind === "hidden-columns"
              return (
                <motion.li
                  key={f.id}
                  layout={!reduce}
                  data-finding={f.id}
                  initial={reduce ? { opacity: 0 } : { opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0, transition: { delay: reduce ? 0 : i * 0.05 } }}
                  exit={{ opacity: 0, transition: { duration: 0.15 } }}
                  className={cn("grid min-w-0 gap-2 rounded-md border p-2.5", isKept ? tone.low : tone[f.severity])}
                >
                  <div className="flex min-w-0 items-start gap-2">
                    <EyeOff aria-hidden className={cn("mt-0.5 size-4 shrink-0", f.severity === "high" && !isKept ? "text-red-600 dark:text-red-400" : "text-muted-foreground")} />
                    <div className="grid min-w-0 flex-1 gap-0.5">
                      <span className="font-medium break-words">{fill(m.kind[f.kind], { count: fmt(f.count), where: f.where ?? "" })}</span>
                      {f.veryHidden && <span className="text-xs text-muted-foreground">{m.veryHidden}</span>}
                    </div>
                  </div>
                  <AnimatePresence initial={false}>
                    {showing && f.preview.length > 0 && (
                      <motion.div
                        id={`${id}-${i}`}
                        initial={reduce ? { opacity: 0 } : { opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: "auto" }}
                        exit={reduce ? { opacity: 0 } : { opacity: 0, height: 0 }}
                        transition={{ duration: 0.2, ease: "easeOut" }}
                        className="overflow-hidden"
                      >
                        {table ? (
                          <div tabIndex={0} role="region" aria-label={fill(m.kind[f.kind], { count: fmt(f.count), where: f.where ?? "" })} className="overflow-x-auto rounded-sm border bg-background outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
                            <table className="w-full font-mono text-[11px]">
                              <tbody>
                                {f.preview.map((row, r) => (
                                  <tr key={r} className={cn("border-b last:border-0", r === 0 && "font-semibold")}>
                                    {row.map((cell, c) => (
                                      <td key={c} className="border-r px-1.5 py-1 whitespace-nowrap last:border-r-0">
                                        {cell}
                                      </td>
                                    ))}
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        ) : (
                          <ul className="grid gap-1 text-xs">
                            {f.preview.map((row, r) => (
                              <li key={r} className="rounded-sm bg-background px-2 py-1 break-words [overflow-wrap:anywhere]">
                                {f.kind === "tracked-changes" ? <del>{row[0]}</del> : row[0]}
                              </li>
                            ))}
                          </ul>
                        )}
                      </motion.div>
                    )}
                  </AnimatePresence>
                  <div className="flex flex-wrap items-center gap-1.5">
                    {f.preview.length > 0 && (
                      <button type="button" aria-expanded={showing} aria-controls={showing ? `${id}-${i}` : undefined} onClick={() => setOpen(showing ? null : f.id)} className={chip}>
                        <ChevronDown aria-hidden className={cn("size-3.5 transition-transform", showing && "rotate-180")} />
                        {showing ? m.hide : m.show}
                      </button>
                    )}
                    {f.severity !== "low" &&
                      (isKept ? (
                        <span className="inline-flex h-7 items-center gap-1 px-1 text-xs text-muted-foreground">
                          <Check aria-hidden className="size-3.5" />
                          {m.kept}
                        </span>
                      ) : (
                        <button type="button" onClick={() => keep(f)} className={chip}>
                          {m.keep}
                        </button>
                      ))}
                    {onRemove && !isKept && (
                      <button type="button" disabled={busy !== null} aria-busy={busy === f.id} onClick={() => remove(f)} className={chip}>
                        {busy === f.id ? <Loader2 aria-hidden className="size-3.5 animate-spin" /> : <Trash2 aria-hidden className="size-3.5" />}
                        {busy === f.id ? m.removing : m.remove}
                      </button>
                    )}
                  </div>
                  {notes[f.id] && <p role="alert" className="text-xs text-red-700 dark:text-red-400">{notes[f.id]}</p>}
                </motion.li>
              )
            })}
          </AnimatePresence>
        </ul>
      )}

      {findings.some((f) => f.kind === "hidden-sheet" || f.kind === "hidden-rows" || f.kind === "hidden-columns") && <p className="text-xs text-muted-foreground">{m.advice}</p>}

      {onShare && current && (
        <div className="grid gap-1.5">
          <button
            ref={shareRef}
            type="button"
            disabled={!report || sharing}
            aria-describedby={warn ? `${id}-blocked` : undefined}
            onClick={share}
            className={cn(
              "inline-flex h-9 w-fit max-w-full items-center gap-2 rounded-md px-4 text-sm font-medium shadow-xs outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-60",
              warn ? "bg-destructive text-white hover:bg-destructive/90" : "bg-primary text-primary-foreground hover:bg-primary/90",
            )}
          >
            {sharing && <Loader2 aria-hidden className="size-4 animate-spin" />}
            <span className="truncate">{sharing ? m.sharing : warn ? (open_.length ? fill(m.shareAnyway, { count: open_.length }) : m.shareUnchecked) : fill(m.share, { file: name })}</span>
          </button>
          {warn && (
            <p id={`${id}-blocked`} role="alert" className="text-xs text-amber-700 dark:text-amber-400">
              {open_.length ? fill(m.blocked, { count: open_.length }) : m.blockedUnchecked}
            </p>
          )}
        </div>
      )}
      <span role="status" className="sr-only">
        {status}
      </span>
    </section>
  )
}

// Bollard UI — hidden-content-check · MIT licence · https://bollard-ui.vercel.app/components/hidden-content-check

/**
 * Reads an Office Open XML file (.xlsx, .docx, .pptx) in the browser or on the server and lists what is
 * inside it that the person sharing it can't see on screen: hidden and "very hidden" sheets, hidden
 * rows and columns, comments, tracked deletions, hidden text, speaker notes, hidden slides, embedded
 * files (a chart's whole source workbook rides inside a deck), links to files on internal drives and
 * author details. No dependencies: the zip is read by hand and inflated with the platform's
 * DecompressionStream("deflate-raw").
 */

export type HiddenKind =
  | "hidden-sheet"
  | "hidden-rows"
  | "hidden-columns"
  | "tracked-changes"
  | "hidden-text"
  | "comments"
  | "speaker-notes"
  | "hidden-slides"
  | "embedded-files"
  | "external-links"
  | "author"

export type HiddenSeverity = "high" | "medium" | "low"

export interface HiddenFinding {
  /** Stable id, e.g. "hidden-sheet:SAP export". */
  id: string
  kind: HiddenKind
  severity: HiddenSeverity
  /** How many: rows in a hidden sheet, hidden columns, comments, changes, notes… */
  count: number
  /** Sheet or part it sits in, when there is one. */
  where?: string
  /** A sheet hidden with state="veryHidden", which Excel's Unhide menu doesn't list. */
  veryHidden?: boolean
  /** Sample of the hidden content: table rows for sheets, passages of text otherwise. */
  preview: string[][]
}

export interface HiddenReport {
  format: "xlsx" | "docx" | "pptx" | "other"
  findings: HiddenFinding[]
  /** Set when the file couldn't be read: `locked` is an old binary (.xls/.doc) or password-protected file. */
  error?: "locked" | "unreadable" | "too-large"
}

const MAX_BYTES = 200 * 1024 * 1024
const MAX_PART = 64 * 1024 * 1024
const SEVERITY: Record<HiddenKind, HiddenSeverity> = {
  "hidden-sheet": "high", "tracked-changes": "high", "hidden-text": "high", "hidden-rows": "medium", "hidden-columns": "medium",
  comments: "medium", "speaker-notes": "medium", "hidden-slides": "medium", "embedded-files": "medium", "external-links": "medium", author: "low",
}

type Zip = Map<string, () => Promise<Uint8Array>>

/** Lists a zip's entries with lazy readers. Returns null for anything that isn't a readable zip (ZIP64 included). */
export function readZip(bytes: Uint8Array): Zip | null {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  let eocd = -1
  for (let i = bytes.length - 22; i >= Math.max(0, bytes.length - 65557); i--) {
    if (view.getUint32(i, true) === 0x06054b50) { eocd = i; break }
  }
  if (eocd < 0) return null
  const count = view.getUint16(eocd + 10, true)
  let p = view.getUint32(eocd + 16, true)
  const zip: Zip = new Map()
  const names = new TextDecoder()
  for (let n = 0; n < count && p + 46 <= bytes.length; n++) {
    if (view.getUint32(p, true) !== 0x02014b50) return null
    const method = view.getUint16(p + 10, true)
    const size = view.getUint32(p + 20, true)
    const full = view.getUint32(p + 24, true)
    const nameLen = view.getUint16(p + 28, true)
    const skip = nameLen + view.getUint16(p + 30, true) + view.getUint16(p + 32, true)
    const local = view.getUint32(p + 42, true)
    const name = names.decode(bytes.subarray(p + 46, p + 46 + nameLen))
    p += 46 + skip
    if (local + 30 > bytes.length || full > MAX_PART) continue
    const start = local + 30 + view.getUint16(local + 26, true) + view.getUint16(local + 28, true)
    const data = bytes.subarray(start, start + size)
    zip.set(name.replace(/^\//, ""), async () => {
      if (method === 0) return data
      if (method !== 8) throw new Error("unsupported compression")
      const stream = new Blob([data as BlobPart]).stream().pipeThrough(new DecompressionStream("deflate-raw"))
      return new Uint8Array(await new Response(stream).arrayBuffer())
    })
  }
  return zip
}

const decoder = new TextDecoder()
async function text(zip: Zip, name: string) {
  const read = zip.get(name)
  if (!read) return ""
  try {
    return decoder.decode(await read()).replace(/^\uFEFF/, "")
  } catch {
    return ""
  }
}

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" }
const unescape = (s: string) =>
  s.replace(/&(#x[\da-f]+|#\d+|\w+);/gi, (m, e: string) =>
    e[0] === "#" ? String.fromCodePoint(parseInt(e[1] === "x" || e[1] === "X" ? e.slice(2) : e.slice(1), e[1] === "x" || e[1] === "X" ? 16 : 10) || 32) : ENTITIES[e] ?? m)
const attr = (tag: string, name: string) => unescape(new RegExp(`\\s${name}="([^"]*)"`).exec(tag)?.[1] ?? "")
/** Text of every <prefix:t> run in a fragment, joined. */
const runs = (xml: string, tag: string) => [...xml.matchAll(new RegExp(`<${tag}(?:\\s[^>]*)?>([^<]*)</${tag}>`, "g"))].map((m) => unescape(m[1])).join("")
const clip = (s: string, n = 140) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s)
const isOn = (tag: string) => !/\sw:val="(0|false|off)"/.test(tag)
const resolve = (base: string, target: string) => {
  if (target.startsWith("/")) return target.slice(1)
  const parts = base.split("/").slice(0, -1)
  for (const seg of target.split("/")) seg === ".." ? parts.pop() : seg !== "." && parts.push(seg)
  return parts.join("/")
}
const rels = async (zip: Zip, part: string) => {
  const slash = part.lastIndexOf("/")
  const xml = await text(zip, `${part.slice(0, slash)}/_rels/${part.slice(slash + 1)}.rels`)
  return new Map([...xml.matchAll(/<Relationship\s[^>]*>/g)].map((m) => [attr(m[0], "Id"), { target: attr(m[0], "Target"), external: attr(m[0], "TargetMode") === "External" }]))
}

const safeDecode = (s: string) => {
  try {
    return decodeURI(s)
  } catch {
    return s
  }
}
/** A link into a file share or company drive rather than the public web. */
export const isInternalLink = (target: string) =>
  /^(file:|\\\\|smb:|[a-z]:[\\/])/i.test(target) || /^https?:\/\/[^/]*(\.sharepoint\.com|\.internal|\.local|\.corp|intranet)[/:]/i.test(target)

/** "D12" → 3. Returns -1 without a column reference. */
const colIndex = (ref: string) => {
  const letters = /^([A-Z]{1,3})\d/i.exec(ref)?.[1]?.toUpperCase()
  if (!letters) return -1
  let n = 0
  for (const ch of letters) n = n * 26 + ch.charCodeAt(0) - 64
  return n - 1
}

/**
 * Every row of a worksheet as cell strings, shared strings resolved. Cells sit at their real column
 * (Excel leaves empty cells out, so "A1, D1" must land at 0 and 3, not 0 and 1).
 */
function sheetRows(xml: string, shared: string[]) {
  const rows: { hidden: boolean; cells: string[] }[] = []
  for (const row of xml.matchAll(/<row(\s[^>]*)?(?:\/>|>([\s\S]*?)<\/row>)/g)) {
    const cells: string[] = []
    let next = 0
    for (const c of (row[2] ?? "").matchAll(/<c(\s[^>]*)?(?:\/>|>([\s\S]*?)<\/c>)/g)) {
      const type = attr(c[1] ?? "", "t")
      const body = c[2] ?? ""
      const v = unescape(/<v>([^<]*)<\/v>/.exec(body)?.[1] ?? "")
      const at = colIndex(attr(c[1] ?? "", "r"))
      const col = at >= 0 && at < 16384 ? at : next
      while (cells.length < col) cells.push("")
      cells[col] = type === "inlineStr" ? runs(body, "t") : type === "s" ? shared[Number(v)] ?? "" : v
      next = col + 1
    }
    rows.push({ hidden: /\shidden="(1|true)"/.test(row[1] ?? ""), cells })
  }
  return rows
}
const sample = (rows: { cells: string[] }[]) => rows.filter((r) => r.cells.some(Boolean)).slice(0, 3).map((r) => r.cells.slice(0, 6).map((c) => clip(c, 40)))

async function xlsx(zip: Zip, out: HiddenFinding[]) {
  const book = await text(zip, "xl/workbook.xml")
  const links = await rels(zip, "xl/workbook.xml")
  const shared = [...(await text(zip, "xl/sharedStrings.xml")).matchAll(/<si>([\s\S]*?)<\/si>/g)].map((m) => runs(m[1], "t"))
  for (const tag of book.match(/<sheet\s[^>]*>/g) ?? []) {
    const name = attr(tag, "name")
    const state = attr(tag, "state")
    const target = links.get(/\s[\w]+:id="([^"]*)"/.exec(tag)?.[1] ?? "")?.target
    const sheetXml = target ? await text(zip, resolve("xl/workbook.xml", target)) : ""
    const rows = sheetRows(sheetXml, shared)
    const filled = rows.filter((r) => r.cells.some(Boolean))
    if (state === "hidden" || state === "veryHidden") {
      out.push({ id: `hidden-sheet:${name}`, kind: "hidden-sheet", severity: "high", count: filled.length, where: name, veryHidden: state === "veryHidden", preview: sample(rows) })
      continue
    }
    const hiddenRows = rows.filter((r) => r.hidden && r.cells.some(Boolean))
    if (hiddenRows.length) out.push({ id: `hidden-rows:${name}`, kind: "hidden-rows", severity: "medium", count: hiddenRows.length, where: name, preview: sample(hiddenRows) })
    const cols = (sheetXml.match(/<col\s[^>]*>/g) ?? []).filter((c) => /\shidden="(1|true)"/.test(c))
    const indexes = cols.flatMap((c) => {
      const min = Number(attr(c, "min")) || 1
      const max = Math.min(Number(attr(c, "max")) || min, min + 16383)
      return Array.from({ length: max - min + 1 }, (_, i) => min - 1 + i)
    })
    // Only columns that hold something count; a styled empty range isn't a leak.
    const used = indexes.filter((i) => filled.some((r) => r.cells[i]))
    if (used.length) {
      out.push({ id: `hidden-columns:${name}`, kind: "hidden-columns", severity: "medium", count: used.length, where: name, preview: filled.slice(0, 3).map((r) => used.slice(0, 6).map((i) => clip(r.cells[i] ?? "", 40))) })
    }
  }
  const notes: string[][] = []
  for (const part of [...zip.keys()].filter((k) => /^xl\/(comments\d*|threadedComments\/[^/]+)\.xml$/.test(k))) {
    const xml = await text(zip, part)
    for (const c of xml.matchAll(/<(?:comment|threadedComment)\s[^>]*>([\s\S]*?)<\/(?:comment|threadedComment)>/g)) {
      const body = runs(c[1], "t") || runs(c[1], "text")
      // Excel mirrors every threaded comment into the legacy comments part with this stub; count it once.
      if (/^\s*\[Threaded comment\]/.test(body)) continue
      notes.push([clip(body)])
    }
  }
  if (notes.length) out.push({ id: "comments", kind: "comments", severity: "medium", count: notes.length, preview: notes.slice(0, 3) })
  const external: string[][] = []
  for (const part of [...zip.keys()].filter((k) => /^xl\/externalLinks\/[^/]+\.xml$/.test(k))) {
    for (const r of (await rels(zip, part)).values()) if (r.external) external.push([safeDecode(r.target)])
  }
  if (external.length) out.push({ id: "external-links", kind: "external-links", severity: "medium", count: external.length, preview: external.slice(0, 3) })
}

async function docx(zip: Zip, out: HiddenFinding[]) {
  const doc = await text(zip, "word/document.xml")
  const changes = (doc.match(/<w:(ins|del|moveFrom|moveTo)[\s>]/g) ?? []).length
  const deleted = [...doc.matchAll(/<w:del\s[^>]*[^/]>([\s\S]*?)<\/w:del>/g)].map((m) => runs(m[1], "w:delText")).filter((s) => s.trim())
  if (changes) out.push({ id: "tracked-changes", kind: "tracked-changes", severity: "high", count: changes, preview: deleted.slice(0, 3).map((s) => [clip(s)]) })
  const hidden = [...doc.matchAll(/<w:r[\s>](?:(?!<\/w:r>)[\s\S])*?<\/w:r>/g)]
    .filter((m) => { const v = /<w:vanish(\s[^>]*)?\/>/.exec(m[0]); return !!v && isOn(v[0]) })
    .map((m) => runs(m[0], "w:t")).filter((s) => s.trim())
  if (hidden.length) out.push({ id: "hidden-text", kind: "hidden-text", severity: "high", count: hidden.length, preview: hidden.slice(0, 3).map((s) => [clip(s)]) })
  const comments = [...(await text(zip, "word/comments.xml")).matchAll(/<w:comment\s([^>]*)>([\s\S]*?)<\/w:comment>/g)]
  if (comments.length) out.push({ id: "comments", kind: "comments", severity: "medium", count: comments.length, preview: comments.slice(0, 3).map((c) => [clip(`${attr(c[1], "w:author") ? `${attr(c[1], "w:author")}: ` : ""}${runs(c[2], "w:t")}`)]) })
}

const slideNo = (k: string) => Number(/(\d+)\.xml$/.exec(k)?.[1] ?? 0)
async function pptx(zip: Zip, out: HiddenFinding[]) {
  const slides = [...zip.keys()].filter((k) => /^ppt\/slides\/slide\d+\.xml$/.test(k)).sort((a, b) => slideNo(a) - slideNo(b))
  const hidden: string[][] = []
  for (const s of slides) {
    const xml = await text(zip, s)
    if (/<p:sld\s[^>]*\sshow="(0|false)"/.test(xml)) hidden.push([`${slideNo(s)}. ${clip(runs(xml, "a:t"), 100)}`])
  }
  if (hidden.length) out.push({ id: "hidden-slides", kind: "hidden-slides", severity: "medium", count: hidden.length, preview: hidden.slice(0, 3) })
  const notes: string[][] = []
  for (const n of [...zip.keys()].filter((k) => /^ppt\/notesSlides\/notesSlide\d+\.xml$/.test(k)).sort((a, b) => slideNo(a) - slideNo(b))) {
    const body = runs((await text(zip, n)).replace(/<a:fld\s[\s\S]*?<\/a:fld>/g, ""), "a:t").trim()
    if (body) notes.push([clip(body)])
  }
  if (notes.length) out.push({ id: "speaker-notes", kind: "speaker-notes", severity: "medium", count: notes.length, preview: notes.slice(0, 3) })
  const comments = [...zip.keys()].filter((k) => /^ppt\/comments\/[^/]+\.xml$/.test(k))
  let count = 0
  const preview: string[][] = []
  for (const c of comments) {
    for (const m of (await text(zip, c)).matchAll(/<\w+:cm\s[^>]*>([\s\S]*?)<\/\w+:cm>/g)) {
      count++
      preview.push([clip(runs(m[1], "p:text") || runs(m[1], "a:t"))])
    }
  }
  if (count) out.push({ id: "comments", kind: "comments", severity: "medium", count, preview: preview.slice(0, 3) })
}

/**
 * Lists what an .xlsx, .docx or .pptx carries that isn't visible on screen. Accepts a Blob/File, an
 * ArrayBuffer or bytes. Never throws: unreadable input comes back with `error` set.
 */
export async function inspectHiddenContent(input: Blob | ArrayBuffer | Uint8Array | null | undefined, depth = 0): Promise<HiddenReport> {
  if (!input) return { format: "other", findings: [], error: "unreadable" }
  try {
    const size = input instanceof Uint8Array ? input.byteLength : input instanceof ArrayBuffer ? input.byteLength : input.size
    if (size > MAX_BYTES) return { format: "other", findings: [], error: "too-large" }
    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input instanceof ArrayBuffer ? input : await input.arrayBuffer())
    // D0 CF 11 E0: an OLE container, i.e. a legacy .xls/.doc/.ppt or an encrypted OOXML file.
    if (bytes[0] === 0xd0 && bytes[1] === 0xcf && bytes[2] === 0x11 && bytes[3] === 0xe0) return { format: "other", findings: [], error: "locked" }
    const zip = bytes.length > 22 ? readZip(bytes) : null
    if (!zip) return { format: "other", findings: [], error: "unreadable" }
    const format = zip.has("xl/workbook.xml") ? "xlsx" : zip.has("word/document.xml") ? "docx" : zip.has("ppt/presentation.xml") ? "pptx" : "other"
    const findings: HiddenFinding[] = []
    if (format === "xlsx") await xlsx(zip, findings)
    if (format === "docx") await docx(zip, findings)
    if (format === "pptx") await pptx(zip, findings)
    const embedded = [...zip.keys()].filter((k) => /^(xl|word|ppt)\/embeddings\/[^/]+$/.test(k))
    if (embedded.length) {
      const preview: string[][] = []
      for (const e of embedded.slice(0, 3)) {
        const name = e.split("/").pop() ?? e
        // A chart's source workbook: say what it holds, one level deep.
        const inner = depth === 0 && /\.xlsx$/i.test(name) ? await inspectHiddenContent(await zip.get(e)!(), 1) : null
        const sheets = inner?.findings.filter((f) => f.kind === "hidden-sheet").length
        preview.push([sheets ? `${name} (${sheets} hidden sheet${sheets > 1 ? "s" : ""} inside)` : name])
      }
      findings.push({ id: "embedded-files", kind: "embedded-files", severity: "medium", count: embedded.length, preview })
    }
    if (format === "docx" || format === "pptx") {
      // Hyperlinks to file shares and internal drives reveal server names, folder structure and file names.
      const internal = new Set<string>()
      for (const part of [...zip.keys()].filter((k) => /^(word|ppt)\/(?:[^/]+\/)*_rels\/[^/]+\.rels$/.test(k))) {
        for (const m of (await text(zip, part)).matchAll(/<Relationship\s[^>]*>/g)) {
          const target = attr(m[0], "Target")
          if (attr(m[0], "TargetMode") === "External" && isInternalLink(target)) internal.add(safeDecode(target))
        }
      }
      if (internal.size) findings.push({ id: "external-links", kind: "external-links", severity: "medium", count: internal.size, preview: [...internal].slice(0, 3).map((t) => [clip(t)]) })
    }
    const core = await text(zip, "docProps/core.xml")
    const app = await text(zip, "docProps/app.xml")
    const people = [["Author", runs(core, "dc:creator")], ["Last saved by", runs(core, "cp:lastModifiedBy")], ["Company", runs(app, "Company")], ["Manager", runs(app, "Manager")]]
      .filter(([, v]) => v.trim())
    if (people.length) findings.push({ id: "author", kind: "author", severity: "low", count: people.length, preview: people.map(([k, v]) => [`${k}: ${clip(v, 60)}`]) })
    const rank = { high: 0, medium: 1, low: 2 }
    return { format, findings: findings.map((f) => ({ ...f, severity: SEVERITY[f.kind] })).sort((a, b) => rank[a.severity] - rank[b.severity]) }
  } catch {
    return { format: "other", findings: [], error: "unreadable" }
  }
}
